/**
 * ZP Suite v2.2.398 — trust logos spacing/size/position + hero desktop width 1750.
 */
add_action('init', function(){
  $ver_key = 'zp_suite_front_fixes_237_v397';
  if (get_option($ver_key) === '1') { return; }

  $opts = get_option('zp_suite_options', []);
  if (!is_array($opts)) { $opts = []; }
  if (empty($opts['stats']) || !is_array($opts['stats'])) { $opts['stats'] = []; }
  if (empty($opts['hero']) || !is_array($opts['hero'])) { $opts['hero'] = []; }
  $opts['stats']['trustindex_reviews'] = 50;
  $opts['hero']['trust_reviews'] = 50;
  update_option('zp_suite_options', $opts, false);

  $kat_rows = get_option('zp_suite_katowice_page', []);
  if (is_array($kat_rows)) {
    if (!empty($kat_rows[0]) && is_array($kat_rows[0])) {
      $kat_rows[0]['hero_h1'] = 'Strony internetowe Katowice — strony firmowe gotowe na SEO i zapytania';
    } else {
      $kat_rows = [[
        'hero_kicker' => 'Strony internetowe Katowice / WordPress / SEO',
        'hero_h1' => 'Strony internetowe Katowice — strony firmowe gotowe na SEO i zapytania',
      ]];
    }
    update_option('zp_suite_katowice_page', $kat_rows, false);
  }

  // Starsze patche mogły zapisać H1 w osobnym kluczu jako tablicę asocjacyjną — czyścimy to twardo.
  $kat_legacy = get_option('zp_suite_katowice_page_legacy', []);
  if (is_array($kat_legacy)) {
    $kat_legacy['hero_h1'] = 'Strony internetowe Katowice — strony firmowe gotowe na SEO i zapytania';
    update_option('zp_suite_katowice_page_legacy', $kat_legacy, false);
  }

  // Refresh only hero sections where content is stored in options.
  if (function_exists('zp_suite_shop_katowice_default_section')) {
    $sections = get_option('zp_suite_shop_katowice_sections', []);
    if (!is_array($sections)) { $sections = []; }
    $sections['hero'] = zp_suite_shop_katowice_default_section('hero');
    update_option('zp_suite_shop_katowice_sections', $sections, false);
  }

  update_option($ver_key, '1', false);
}, 20);


