/**
 * ZP Suite v2.7.17 — unify public review counters.
 * Trustindex: 120 total reviews. Facebook: 60 reviews.
 */
add_action('init', function(){
  $ver_key = 'zp_suite_reviews_counts_2717';
  if (get_option($ver_key) === '1') { return; }

  $opts = get_option('zp_suite_options', []);
  if (!is_array($opts)) { $opts = []; }
  if (empty($opts['stats']) || !is_array($opts['stats'])) { $opts['stats'] = []; }
  if (empty($opts['hero']) || !is_array($opts['hero'])) { $opts['hero'] = []; }

  $opts['stats']['trustindex_reviews'] = '120';
  $opts['stats']['facebook_reviews'] = '60';
  $opts['hero']['trust_reviews'] = '120';
  $opts['hero']['fb_reviews'] = '60';

  update_option('zp_suite_options', $opts, false);
  update_option($ver_key, '1', false);
}, 21);
